const spoken=e==="te"?`${mkt}లో నేడు ${cName} మోడల్ ధర క్వింటాలుకు ₹${crop.modal.toLocaleString("en-IN")}.`:e==="hi"?`${mkt} में आज ${cName} का मॉडल भाव ₹${crop.modal.toLocaleString("en-IN")} प्रति क्विंटल है।`:`Today's modal selling price for ${cName} at ${mkt} is ₹${crop.modal.toLocaleString("en-IN")} per quintal, with a trading range between ₹${crop.min.toLocaleString("en-IN")} and ₹${crop.max.toLocaleString("en-IN")}.`;
