const getApiBase=()=>{
try{
const p=new URLSearchParams(window.location.search);
const qApi=p.get("api")||p.get("backend");
if(qApi){localStorage.setItem("farmdirect_backend_url",qApi);return qApi.replace(/\/+$/,"")}
}catch(err){}
if(typeof window!=="undefined"&&window.FARMDIRECT_API_BASE)return window.FARMDIRECT_API_BASE.replace(/\/+$/,"");
try{
const sUrl=localStorage.getItem("farmdirect_backend_url");
if(sUrl)return sUrl.replace(/\/+$/,"");
}catch(err){}
if(typeof window!=="undefined"&&window.location.origin)return window.location.origin;
return"";
};

const V=async R=>{
if(!R||!R.trim())return;
const query=R.trim();
u(!0);
const userEntry={role:"user",text:query,timestamp:Date.now()};
s(prev=>[...prev,userEntry]);

let answerText="";
let spokenText="";
let backendErr=null;

const base=getApiBase();
const candidates=[];
if(base){
candidates.push(base+"/api/voice/query");
}else{
candidates.push("/api/voice/query");
if(typeof window!=="undefined"&&window.location.protocol==="http:"){
candidates.push("http://localhost:8000/api/voice/query");
}
}

for(const apiUrl of candidates){
try{
console.log("[VoiceAssistant] Dispatching query to Voice AI backend:",apiUrl,{query,language:e,sessionId:sessionIdRef.current});
const ctrl=new AbortController();
const tId=setTimeout(()=>ctrl.abort(),3500);
const res=await fetch(apiUrl,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({query,language:e,farmer_district:sessionContextRef.current.district||"guntur",session_id:sessionIdRef.current,session_context:sessionContextRef.current}),signal:ctrl.signal});
clearTimeout(tId);
if(res.ok){
const data=await res.json();
console.log("[VoiceAssistant] Backend response received:",data);
if(data.session_id)sessionIdRef.current=data.session_id;
if(data.session_context)sessionContextRef.current=data.session_context;
if(data.extracted_entities&&data.extracted_entities.crop){
sessionContextRef.current.crop_id=data.extracted_entities.crop;
}
answerText=data.visual_answer||data.spoken_answer;
spokenText=data.spoken_answer||data.visual_answer;
backendErr=null;
break;
}else{
backendErr=`HTTP ${res.status} (${res.statusText||"Error"}) from ${apiUrl}`;
console.error("[VoiceAssistant] "+backendErr);
}
}catch(err){
backendErr=`Connection failed to ${apiUrl}: ${err.message||err}`;
console.error("[VoiceAssistant] "+backendErr);
}
}

if(!answerText){
console.warn("[VoiceAssistant] Backend API unreachable. Generating verified local CROP_DATA response. Error:",backendErr);
let notice="";
if(typeof window!=="undefined"&&(window.location.hostname.includes("bolt.host")||window.location.hostname.includes("bolt.new"))){
notice=`⚠️ [Backend Connection Notice]: Voice AI backend is unreachable from Bolt.host (${backendErr||"Network timeout"}).\n👉 Connect live backend via ?api=https://... or run locally at http://localhost:8000/.\n\n`;
}
const local=E(query);
answerText=notice+local.visual;
spokenText=local.spoken;
}

const botEntry={role:"assistant",text:answerText,timestamp:Date.now()};
s(prev=>[...prev,botEntry]);
N(spokenText);
u(!1);
};

